const userEmail = ($json.body.user_email || '').trim().toLowerCase();
if (!userEmail) throw new Error('user_email is required in request body');
return [{ json: { userEmail } }];

const trigger = $('Manual Proposal Trigger').item.json.body;
const pricingRows = $input.all().map(i => i.json);

const rawId = (trigger.request_id || '').toString().trim();
const meetingId = rawId.length > 0 ? rawId : `manual-${Date.now()}`;

const validDays = parseInt(trigger.valid_days) || 30;
const validUntil = new Date();
validUntil.setDate(validUntil.getDate() + validDays);
const formatDate = (d) => d.toISOString().split('T')[0];

let bodyHtml = (trigger.proposal_body || '').trim();
if (!/<[a-z][\s\S]*>/i.test(bodyHtml)) {
  bodyHtml = bodyHtml
    .split(/\n{2,}/)
    .map(para => `<p>${para.replace(/\n/g, '<br>')}</p>`)
    .join('');
}

return [{
  json: {
    meeting_id: meetingId,
    lead_email: trigger.lead_email,
    overview: `Manual proposal drafted for ${trigger.lead_name}`,
    requirements: {
      budget_signal: null,
      timeline: null,
      key_requirements: [],
      pain_points: [],
      objections_raised: [],
      competitors_mentioned: [],
      decision_makers: []
    },
    pricing_catalog_json: pricingRows,
    proposal: {
      subject: trigger.proposal_subject,
      body_html: bodyHtml,
      package_selected: (trigger.proposal_template || '').trim(),
      quoted_price: Number(trigger.quoted_price),
      valid_until: formatDate(validUntil)
    }
  }
}];
